using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class DuplicateKeyGeneratorReceipts
{
    [Fact]
    public async Task DuplicateIntKey_IsNotSilentlyDropped()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }

                [MessagePackObject]
                public class DupKeys
                {
                    [Key(0)]
                    public int FirstValue { get; set; }

                    [Key(0)]
                    public int SecondValue { get; set; }
                }
            }
            """;

        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();

        var compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);

        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        GeneratorDriverRunResult result = driver.GetRunResult();

        bool failedLoudly = result.Results.Any(r => r.Exception is not null) || result.Diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error);
        string generated = string.Join("\n", result.GeneratedTrees.Select(t => t.ToString()));
        bool serializesBoth = generated.Contains("FirstValue") && generated.Contains("SecondValue");

        Assert.True(
            failedLoudly || serializesBoth,
            "Two members share Key(0); the generator neither reported a problem nor serialized both members, so SecondValue is silently lost. Generated:\n" + generated);
    }
}
